// Generated by vibelang from src/updater/action.ts; the migrate flow writes it again with each batch.
/** The one update action the settings row and the titlebar pill offer for a state. */
export function updaterAction(state) {
    if (!state)
        return { label: "action.checkNow" };
    switch (state.status) {
        case "checking":
            return { label: "action.checking" };
        case "downloading":
            return { label: "action.downloading" };
        case "ready":
            return { label: "action.installRestart", run: "install" };
        case "download-required":
            return { label: "action.download", run: "install" };
        case "installing":
            return { label: "action.installing" };
        case "disabled":
            return { label: "action.checkNow" };
        default:
            return { label: "action.checkNow", run: "check" };
    }
}
